=COUNT(
 SELECT(
 Borrowers[Row ID],
 AND(
 [Row ID] <> [_THISROW].[Row ID],
 LOWER(TRIM([Borrower Name])) = LOWER(TRIM([_THISROW].[Borrower Name]))
 )
 )
) = 0

=AND(
 [_THIS] >= 0,
 [_THIS] <= (
 [Ref Charges].[Principal Due]
 - SUM(
 SELECT(
 Repayments[Principal Paid],
 AND(
 [Ref Charges] = [_THISROW].[Ref Charges],
 [Row ID] <> [_THISROW].[Row ID]
 )
 )
 )
 )
)

=COUNT(
 SELECT(
 Borrowers[Row ID],
 [Daily Collection Status] = "Fully Paid"
 )
) > 0

=COUNT(
 SELECT(
 Borrowers[Row ID],
 [Daily Collection Status] = "Partially Paid"
 )
) > 0

=COUNT(
 SELECT(
 Borrowers[Row ID],
 [Daily Collection Status] = "Not Paid"
 )
) > 0

=AND(
 [_THIS] >= 0,
 [_THIS] <= (
 [Ref Charges].[Principal Due]
 - SUM(
 SELECT(
 Repayments[Principal Paid],
 AND(
 [Ref Charges] = [_THISROW].[Ref Charges],
 [Row ID] <> [_THISROW].[Row ID]
 )
 )
 )
 )
)

=[_THIS] <= (
[Ref Charges].[Interest Due]
- SUM(
 SELECT(
 Repayments[Interest Paid],
 AND([Ref Charges] = [_THISROW].[Ref Charges], [Row ID] <> [_THISROW].[Row ID])
 )
)
)

=AND(
 [_THIS] > 0,
 OR(
 [Transaction Type] = "Contribution",
 AND(
 [Transaction Type] = "Withdrawal",
 [_THIS] <= SUM(
 SELECT(
 Cash Pool Contributions[Net Contribution],
 AND(
 [Ref Partner] = [_THISROW].[Ref Partner],
 [Contribution Date] <= [_THISROW].[Contribution Date],
 [Row ID] <> [_THISROW].[Row ID]
 )
 )
 )
 )
 )
)
